<script setup lang="ts">
import {ref,watch} from 'vue';import {router,useForm,usePage} from '@inertiajs/vue3';
import {Check,Undo2,Pencil,Link2,Search,X,History,Trash2} from 'lucide-vue-next';
import Pagination from './Pagination.vue';import Modal from './Modal.vue';import DateField from './DateField.vue';import HistoryPanel from './HistoryPanel.vue';
import LoadingState from './LoadingState.vue';import ConfirmDialog from './ConfirmDialog.vue';
import {json,money,dateLabel,dollars} from '../lib/format';
const props=defineProps<{id:string;catalog:any}>();
const emit=defineEmits<{close:[];edit:[data:any];remove:[data:any];navigate:[id:string]}>();
const processing=ref(false);const page=usePage<any>();const detail=ref<any>();const error=ref('');const query=ref('');const results=ref<any>();const showHidden=ref(false);const tab=ref('payment');
const form=useForm<any>({command_key:crypto.randomUUID(),lock_version:1,completed_date:page.props.today,amount:''});
const editingAmount=ref(false);const loading=ref(false),discard=ref(false);let pendingAction:(()=>void)|undefined;let searchNumber=0;
let requestNumber=0;
async function load(){const request=++requestNumber;loading.value=true;error.value='';try{const result=await json('/occurrences/'+props.id+'?show_hidden='+(showHidden.value?'1':'0'));if(request!==requestNumber)return;const dirty=form.isDirty&&Boolean(detail.value);detail.value=result;form.lock_version=result.occurrence.lock_version;form.defaults('lock_version',form.lock_version);if(!dirty){form.completed_date=result.occurrence.completed_date||page.props.today;form.amount=dollars(result.occurrence.amount_cents);form.defaults();}}catch(e:any){if(request===requestNumber)error.value=e.message;}finally{if(request===requestNumber)loading.value=false;}}
watch(()=>props.id,()=>{detail.value=undefined;results.value=undefined;requestNumber++;load();},{immediate:true});watch(showHidden,load);
function action(path:string,data:any={},method:'post'|'patch'|'delete'='post'){if(processing.value)return;processing.value=true;router.visit(path,{method,data:{command_key:crypto.randomUUID(),lock_version:detail.value.occurrence.lock_version,...data},preserveScroll:true,onSuccess:()=>{if('amount' in data)form.defaults('amount',form.amount);if('completed_date' in data)form.defaults('completed_date',form.completed_date);load();},onFinish:()=>processing.value=false,onHttpException:response=>{error.value=response.status===409?'This payment changed. Reload it and try again.':'This change could not be saved.';return false;},onError:errors=>{error.value=Object.values(errors).join(' ');}});}
async function search(url?:string){const number=++searchNumber;try{const result=await json(url||'/occurrences/'+props.id+'/transactions?search='+encodeURIComponent(query.value)+'&show_hidden='+(showHidden.value?'1':'0'));if(number===searchNumber)results.value=result;}catch(e:any){if(number===searchNumber)error.value=e.message;}}
function requestAction(action:()=>void){if(processing.value)return;if(form.isDirty){pendingAction=action;discard.value=true;return;}action();}
function navigate(id:string){requestAction(()=>emit('navigate',id));}
function discardAndContinue(){discard.value=false;pendingAction?.();pendingAction=undefined;}
function categoryPath(id:string){const c=props.catalog.categories.find((c:any)=>c.id===id);return c?(c.parent_id?(props.catalog.categories.find((p:any)=>p.id===c.parent_id)?.name||'Category')+' › ':'')+c.name:'Uncategorized';}
</script>
<template><div><Modal :open="true" :title="detail?.occurrence.name||'Payment details'" :subtitle="detail?(detail.occurrence.kind.replaceAll('_',' ')+' · '+categoryPath(detail.occurrence.category_id)):''" :size="920" :dirty="form.isDirty" :busy="processing" @close="emit('close')"><div class="px-6 py-5">
 <p v-if="error" role="alert" class="mb-4 rounded-md border border-orange-200 bg-orange-50 p-3 text-warning">{{error}}<button class="ml-3 underline" @click="load">Reload</button></p><LoadingState v-if="!detail" :loading="loading" label="Loading payment"/>
 <fieldset v-else :disabled="processing" class="min-w-0"><p v-if="processing" role="status" class="help mb-3">Saving payment…</p><div class="mb-5 flex items-center justify-between rounded-md bg-subtle px-3 py-2"><button class="btn min-h-8! text-xs!" :disabled="!detail.previous_id" @click="navigate(detail.previous_id)">← Previous</button><p class="text-xs font-medium">{{detail.occurrence.kind==='income'?'Expected':'Payment due'}} {{dateLabel(detail.occurrence.due_date)}}</p><button class="btn min-h-8! text-xs!" :disabled="!detail.next_id" @click="navigate(detail.next_id)">Next →</button></div>
 <div v-if="tab!=='history'" class="grid items-start gap-6 md:grid-cols-[.85fr_1.15fr]"><section class="space-y-4"><div><p class="preview-caption">This payment</p><p class="money text-3xl" :class="detail.occurrence.kind==='income'?'text-income':''">{{detail.occurrence.kind==='income'?'+':''}}{{money(detail.occurrence.amount_cents)}}</p><span class="badge mt-3" :class="['paid','received'].includes(detail.occurrence.status)?'badge-info':detail.occurrence.due_date<page.props.today?'badge-warning':''">{{detail.occurrence.status==='unpaid'&&detail.occurrence.due_date<page.props.today?'Overdue':detail.occurrence.status.replaceAll('_',' ')}}</span></div>
 <template v-if="detail.occurrence.kind!=='loan_installment'"><button v-if="!editingAmount&&detail.occurrence.amount_cents!==null" class="text-xs text-income underline" @click="editingAmount=true">Change amount for this payment</button><div v-else class="field"><label for="statement-amount">Amount for this payment · USD</label><div class="flex gap-2"><input id="statement-amount" v-model="form.amount" placeholder="0.00" inputmode="decimal"/><button class="btn" @click="action('/occurrences/'+id,{amount:form.amount},'patch');editingAmount=false">Save</button></div></div></template>
 <div class="field"><label>{{detail.occurrence.kind==='income'?'Received date':'Payment date'}}</label><DateField v-model="form.completed_date" label="Payment date"/></div><div class="flex flex-wrap gap-2"><button v-if="!['paid','received'].includes(detail.occurrence.status)" class="btn-primary" :disabled="detail.occurrence.amount_cents===null" @click="action('/occurrences/'+id+'/complete',{completed_date:form.completed_date})"><Check :size="16"/>{{detail.occurrence.kind==='income'?'Mark as received':'Mark as paid'}}</button><template v-else><button class="btn" @click="action('/occurrences/'+id,{completed_date:form.completed_date},'patch')">Save date</button><button class="text-xs text-muted underline" @click="action('/occurrences/'+id+'/reverse')">{{detail.occurrence.kind==='income'?'Mark as not received':'Mark as unpaid'}}</button></template></div><p class="help">Defaults to today. The payment stays on its due date in the calendar and totals.</p>
 <dl class="grid grid-cols-[90px_1fr] gap-x-3 gap-y-3 rounded-md bg-subtle p-3 text-xs"><template v-if="['income','loan_installment'].includes(detail.occurrence.kind)"><dt class="text-muted">{{detail.occurrence.kind==='income'?'Receiving':'Paying'}} accounts</dt><dd>{{catalog.accounts.filter((a:any)=>detail.occurrence.account_ids.includes(a.id)).map((a:any)=>a.name).join(', ')||'Unassigned'}}</dd></template><dt class="text-muted">Reminders</dt><dd>{{catalog.members.filter((m:any)=>detail.occurrence.recipient_ids.includes(m.id)).map((m:any)=>m.nickname).join(', ')||'None'}}</dd><dt class="text-muted">Assigned to</dt><dd>{{catalog.members.find((m:any)=>m.id===detail.occurrence.member_id)?.nickname||'Entire household'}}</dd></dl><p class="help">{{detail.occurrence.kind==='loan_installment'?'Completing this installment reduces its loan balance and recalculates unpaid installments. Paying-account balances stay unchanged.':'Completing a payment does not create a transaction or change account balances.'}}</p></section>
 <section class="space-y-4"><div><p class="preview-caption">Transactions</p><p class="help">Attaching a transaction doesn’t change the amount or mark the payment paid.</p></div><div class="flex items-center justify-between"><h3 class="text-xs font-medium">Attached · {{detail.attachments.length}}</h3><label class="flex items-center gap-2 text-xs font-normal"><input v-model="showHidden" type="checkbox"/>Show hidden</label></div><div v-for="link in detail.attachments" :key="link.id" class="flex items-center justify-between gap-3 rounded-md border border-line p-3"><div><p class="text-xs font-medium">{{link.display_state==='deleted'?'Deleted transaction':link.display_state==='hidden'?'Hidden transaction':link.transaction.payee}}</p><p v-if="link.display_state==='visible'" class="help mt-1">{{dateLabel(link.transaction.transaction_date)}} · {{money(link.transaction.amount_cents)}}</p></div><button class="btn min-h-8! text-xs!" @click="action('/attachments/'+link.id,{},'delete')">Detach</button></div><p v-if="!detail.attachments.length" class="help rounded-md border border-dashed border-line p-3">No transactions attached yet.</p>
 <h3 class="text-xs font-medium">Suggested matches</h3><p v-if="!detail.suggestions.length" class="help rounded-md border border-dashed border-line p-3">No other matching transactions. Matches use the same amount and seven days around the due date. Bills and subscriptions search all household accounts. Find any transaction below.</p><div v-for="transaction in detail.suggestions" :key="transaction.id" class="flex items-center justify-between gap-3 rounded-md border border-line p-3"><div><p class="text-xs font-medium">{{transaction.payee}}</p><p class="help mt-1">{{dateLabel(transaction.transaction_date)}} · {{money(transaction.amount_cents)}}</p></div><button class="btn min-h-8! text-xs!" @click="action('/occurrences/'+id+'/attachments',{transaction_id:transaction.id})">Attach</button></div>
 <div class="rounded-md border border-line p-3"><h3 class="mb-2 text-xs font-medium">Find a transaction</h3><form class="flex gap-2" @submit.prevent="search()"><input v-model="query" aria-label="Search all transactions" placeholder="Search all accounts"/><button class="btn" aria-label="Search"><Search :size="16"/></button></form><div v-for="transaction in results?.data||[]" :key="transaction.id" class="flex items-center justify-between gap-3 border-b border-line-soft py-3"><div><p class="text-xs font-medium">{{transaction.payee}}</p><p class="help mt-1">{{dateLabel(transaction.transaction_date)}} · {{money(transaction.amount_cents)}}</p></div><button class="btn min-h-8! text-xs!" :disabled="Boolean(transaction.attached_occurrence_id)" @click="action('/occurrences/'+id+'/attachments',{transaction_id:transaction.id})">{{transaction.attached_occurrence_id?'Attached':'Attach'}}</button></div><Pagination :records="results" asynchronous @load="search"/></div></section></div>
 <HistoryPanel v-else :events="detail.history"/>
 </fieldset></div><div v-if="detail" class="sticky bottom-0 flex flex-wrap items-center justify-between gap-3 border-t border-line bg-white px-6 py-4"><div class="flex gap-4"><button v-if="detail.series&&detail.occurrence.kind!=='loan_installment'" class="link-danger text-xs!" @click="requestAction(()=>emit('remove',detail))">Delete…</button><button class="text-xs text-income underline" @click="tab=tab==='history'?'payment':'history'">{{tab==='history'?'Back to payment':'Change history'}}</button></div><div class="flex gap-2"><button v-if="detail.series&&detail.occurrence.kind!=='loan_installment'" class="btn" @click="requestAction(()=>emit('edit',detail))">Edit {{detail.occurrence.kind==='income'?'income':'bill'}}</button><button class="btn-primary" @click="requestAction(()=>emit('close'))">Done</button></div></div>
 <ConfirmDialog :open="discard" title="Discard unsaved payment changes?" @cancel="discard=false;pendingAction=undefined" @confirm="discardAndContinue">The payment date or amount you entered has not been saved.</ConfirmDialog></Modal></div></template>